    def __init__(self):
        self.frames = [[]]
        self.game_over = False

    def roll(self, pins):
        if self.game_over:
            raise IndexError("cannot roll after game is over")
        if pins < 0 or pins > 10:
            raise ValueError("invalid number of pins")

        frame_index = len(self.frames) - 1
        current_frame = self.frames[frame_index]

        if frame_index < 9:
            if len(current_frame) == 0:
                current_frame.append(pins)
                if pins == 10:
                    self.frames.append([])
            elif len(current_frame) == 1:
                if current_frame[0] + pins > 10:
                    raise ValueError(
                        "two rolls in a frame cannot score more than 10 points"
                    )
                current_frame.append(pins)
                self.frames.append([])
            else:
                raise IndexError("cannot roll, frame is already complete")
        else:
            if len(current_frame) == 0:
                current_frame.append(pins)
            elif len(current_frame) == 1:
                first = current_frame[0]
                if first != 10 and first + pins > 10:
                    raise ValueError(
                        "two rolls in a frame cannot score more than 10 points"
                    )
                current_frame.append(pins)
                if first != 10 and first + pins < 10:
                    self.game_over = True
            elif len(current_frame) == 2:
                first, second = current_frame
                if first == 10 and second != 10:
                    if second + pins > 10:
                        raise ValueError("invalid fill balls")
                elif first == 10 and second == 10:
                    pass
                elif first + second == 10:
                    pass
                current_frame.append(pins)
                self.game_over = True
            else:
                raise IndexError("cannot roll after bonus rolls")

    def score(self):
        if not self.game_over:
            raise IndexError("cannot score an incomplete game")

        rolls = [pin for frame in self.frames for pin in frame]

        total = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
"}

